  ws: '80',
  https: '443',
  wss: '443',
  ftp: '21',
}

const HEX = '0123456789abcdefABCDEF'

function isHex(ch) {
  return ch !== undefined && HEX.includes(ch)
}

function asciiLower(text) {
  let out = ''
  for (const ch of text) {
    const code = ch.codePointAt(0)
    out += code >= 0x41 && code <= 0x5a ? String.fromCharCode(code + 32) : ch
  }
  return out
}

function isUnreserved(code) {
  return (
    (code >= 0x41 && code <= 0x5a) ||
    (code >= 0x61 && code <= 0x7a) ||
    (code >= 0x30 && code <= 0x39) ||
    code === 0x2d /* - */ ||
    code === 0x2e /* . */ ||
    code === 0x5f /* _ */ ||
    code === 0x7e /* ~ */
  )
}

