export function parse(text) {
  let rest = text
  let scheme
  for (let i = 0; i < rest.length; i += 1) {
    const ch = rest[i]
    if (ch === '/' || ch === '?' || ch === '#') break
    if (ch === ':') {
      scheme = rest.slice(0, i)
      rest = rest.slice(i + 1)
      break
    }
  }

  let authority
  if (rest.startsWith('//')) {
    rest = rest.slice(2)
    let end = rest.length
    for (let i = 0; i < rest.length; i += 1) {
      const ch = rest[i]
      if (ch === '/' || ch === '?' || ch === '#') {
        end = i
        break
      }
    }
    authority = rest.slice(0, end)
    rest = rest.slice(end)
  }

