export class UriError extends Error {
  constructor(component) {
    super(`the ${component} has a truncated percent-encoding`)
    this.component = component
  }
}

const DEFAULT_PORTS = {
  http: '80',
  ws: '80',
  https: '443',
  wss: '443',
  ftp: '21',
}

const HEX = '0123456789abcdefABCDEF'

function isHex(ch) {
  return ch !== undefined && HEX.includes(ch)
}

function asciiLower(text) {
  let out = ''
  for (const ch of text) {
    const code = ch.codePointAt(0)
    out += code >= 0x41 && code <= 0x5a ? String.fromCharCode(code + 32) : ch
  }
  return out
}

function isUnreserved(code) {
  return (
    (code >= 0x41 && code <= 0x5a) ||
    (code >= 0x61 && code <= 0x7a) ||
    (code >= 0x30 && code <= 0x39) ||
    code === 0x2d /* - */ ||
    code === 0x2e /* . */ ||
    code === 0x5f /* _ */ ||
    code === 0x7e /* ~ */
  )
}

/** Parse a URI reference into its five generic-syntax components. */
export function parse(text) {
  let rest = text
  let scheme
  for (let i = 0; i < rest.length; i += 1) {
    const ch = rest[i]
    if (ch === '/' || ch === '?' || ch === '#') break
    if (ch === ':') {
      scheme = rest.slice(0, i)
      rest = rest.slice(i + 1)
      break
    }
  }

  let authority
  if (rest.startsWith('//')) {
    rest = rest.slice(2)
    let end = rest.length
    for (let i = 0; i < rest.length; i += 1) {
      const ch = rest[i]
      if (ch === '/' || ch === '?' || ch === '#') {
        end = i
        break
      }
    }
    authority = rest.slice(0, end)
    rest = rest.slice(end)
  }

  let fragment
  const hash = rest.indexOf('#')
  if (hash >= 0) {
    fragment = rest.slice(hash + 1)
    rest = rest.slice(0, hash)
  }

  let query
  const mark = rest.indexOf('?')
  if (mark >= 0) {
    query = rest.slice(mark + 1)
    rest = rest.slice(0, mark)
  }

  const uri = { scheme, authority, path: rest, query, fragment }
  Object.assign(uri, splitAuthority(authority))
  return uri
}

function splitAuthority(authority) {
  if (authority === undefined) return { userinfo: undefined, host: undefined, port: undefined }
  let userinfo
  let rest = authority
  const at = rest.lastIndexOf('@')
  if (at >= 0) {
    userinfo = rest.slice(0, at)
    rest = rest.slice(at + 1)
  }
  let port
  let host = rest
  const bracket = rest.lastIndexOf(']')
  const colon = rest.indexOf(':', bracket + 1)
  if (colon >= 0) {
    port = rest.slice(colon + 1)
    host = rest.slice(0, colon)
  }
  return { userinfo, host, port }
}

