  if (uri.authority === undefined) return undefined
  let out = ''
  if (uri.userinfo !== undefined) out += `${uri.userinfo}@`
  out += uri.host ?? ''
  if (uri.port !== undefined) out += `:${uri.port}`
  return out
}

