    if (text[i] !== '%') continue
    if (!isHex(text[i + 1]) || !isHex(text[i + 2])) throw new UriError(component)
  }
}

/** Validate the percent-encodings of a parsed reference, component by component. */
export function checkUri(uri) {
  checkPercent(uri.path, 'path')
  checkPercent(uri.userinfo, 'userinfo')
  checkPercent(uri.host, 'host')
  checkPercent(uri.query, 'query')
  checkPercent(uri.fragment, 'fragment')
}

function normalizePercent(text, component) {
  if (text === undefined) return undefined
  let out = ''
  for (let i = 0; i < text.length; i += 1) {
    const ch = text[i]
    if (ch !== '%') {
      out += ch
      continue
    }
    const a = text[i + 1]
    const b = text[i + 2]
    if (!isHex(a) || !isHex(b)) throw new UriError(component)
