    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = `/${input.slice(3)}`
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = `/${input.slice(4)}`
      output = output.slice(0, Math.max(0, output.lastIndexOf('/')))
    } else if (input === '/..') {
      input = '/'
      output = output.slice(0, Math.max(0, output.lastIndexOf('/')))
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      let end = input.startsWith('/') ? input.indexOf('/', 1) : input.indexOf('/')
      if (end < 0) end = input.length
      output += input.slice(0, end)
      input = input.slice(end)
    }
  }
  return output
}

/** Normalize a parsed reference and return its string form. */
export function normalize(uri) {
  const out = { ...uri }
  if (out.scheme !== undefined) out.scheme = asciiLower(out.scheme)

  out.path = normalizePercent(out.path, 'path')
  out.userinfo = normalizePercent(out.userinfo, 'userinfo')
  out.host = normalizePercent(out.host, 'host')
  out.query = normalizePercent(out.query, 'query')
  out.fragment = normalizePercent(out.fragment, 'fragment')

  if (out.host !== undefined) out.host = asciiLower(out.host)

  if (out.port !== undefined) {
    const fallback = out.scheme === undefined ? undefined : DEFAULT_PORTS[out.scheme]
    if (out.port === '' || (fallback !== undefined && out.port === fallback)) out.port = undefined
  }

  out.path = removeDotSegments(out.path)
  if (out.authority !== undefined && out.path === '') out.path = '/'

  out.authority = joinAuthority(out)
  return format(out)
}

/** Render a parsed reference back to text. */
export function format(uri) {
  let out = ''
  if (uri.scheme !== undefined) out += `${uri.scheme}:`
  if (uri.authority !== undefined) out += `//${uri.authority}`
  out += uri.path
  if (uri.query !== undefined) out += `?${uri.query}`
  if (uri.fragment !== undefined) out += `#${uri.fragment}`
  return out
}

function merge(base, refPath) {
  if (base.authority !== undefined && base.path === '') return `/${refPath}`
  const slash = base.path.lastIndexOf('/')
  if (slash < 0) return refPath
  return base.path.slice(0, slash + 1) + refPath
}

/** RFC 3986 section 5.2.2, strict. Returns a parsed target reference. */
export function resolve(base, ref) {
  let target
  if (ref.scheme !== undefined) {
    target = {
      scheme: ref.scheme,
      authority: ref.authority,
      path: removeDotSegments(ref.path),
      query: ref.query,
    }
    Object.assign(target, splitAuthority(target.authority))
  } else if (ref.authority !== undefined) {
    target = {
      scheme: base.scheme,
      authority: ref.authority,
      path: removeDotSegments(ref.path),
      query: ref.query,
    }
    Object.assign(target, splitAuthority(target.authority))
  } else {
    let path
    let query
    if (ref.path === '') {
      path = base.path
      query = ref.query !== undefined ? ref.query : base.query
    } else {
      path = ref.path.startsWith('/')
        ? removeDotSegments(ref.path)
        : removeDotSegments(merge(base, ref.path))
      query = ref.query
    }
    target = { scheme: base.scheme, authority: base.authority, path, query }
    Object.assign(target, splitAuthority(target.authority))
  }
  target.fragment = ref.fragment
  return target
}
