 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { readFileSync } from 'node:fs'
import { UriError, checkUri, normalize, parse, resolve } from './uri.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function records(input) {
  if (input === '') return []
  const lines = input.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  return lines
}

function main(argv) {
  const mode = argv[0]
  if (argv.length !== 1 || (mode !== 'normalize' && mode !== 'resolve')) {
    fail('usage: cli.js normalize|resolve')
  }

  const lines = records(readStdin())
  const out = []
  for (let i = 0; i < lines.length; i += 1) {
    const number = i + 1
    const line = lines[i]
    try {
      out.push(mode === 'normalize' ? runNormalize(line) : runResolve(line, number))
    } catch (error) {
      if (error instanceof UriError) fail(`line ${number}: ${error.message}`)
      throw error
    }
  }
  process.stdout.write(out.map((line) => `${line}\n`).join(''))
}

function runNormalize(line) {
  const uri = parse(line)
  checkUri(uri)
  return normalize(uri)
}

function runResolve(line, number) {
  const space = line.indexOf(' ')
  if (space < 0) fail(`line ${number}: expected a base and a reference`)
  const base = parse(line.slice(0, space))
  const ref = parse(line.slice(space + 1))
  if (base.scheme === undefined) fail(`line ${number}: the base has no scheme`)
  checkUri(base)
  checkUri(ref)
  return normalize(resolve(base, ref))
}

